function minimumTime(s) {
  const n = s.length;
  let best = Infinity;
  for (let fromLeft = 0; fromLeft <= n; fromLeft++) {
    for (let fromRight = 0; fromLeft + fromRight <= n; fromRight++) {
      const middle = s.slice(fromLeft, n - fromRight);
      const ones = middle.split('').filter(c => c === '1').length;
      best = Math.min(best, fromLeft + fromRight + 2 * ones);
    }
  }
  return best;
}

