function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const density = rand();
  const blocky = rand() < 0.5;
  let out = '';
  let current = rand() < density ? '1' : '0';
  for (let i = 0; i < n; i++) {
    if (blocky) {
      if (rand() < 0.15) current = rand() < density ? '1' : '0';
      out += current;
    } else {
      out += rand() < density ? '1' : '0';
    }
  }
  return [out];
}
